import java.util.*;

class Solution {
  public long maximumValueSum(int[][] board) {
    int m = board.length;
    long[][][] rows = new long[m][][];
    for (int i = 0; i < m; i++) {
      List<long[]> cells = new ArrayList<>();
      for (int j = 0; j < board[i].length; j++) cells.add(new long[] {board[i][j], j});
      rows[i] = top3(cells);
    }
    // pre[i]: best cells (distinct columns) in rows < i; suf[i]: in rows >= i
    long[][][] pre = new long[m + 1][][], suf = new long[m + 1][][];
    pre[0] = new long[0][];
    suf[m] = new long[0][];
    for (int i = 0; i < m; i++) pre[i + 1] = top3(concat(pre[i], rows[i]));
    for (int i = m - 1; i >= 0; i--) suf[i] = top3(concat(suf[i + 1], rows[i]));
    long best = Long.MIN_VALUE;
    // the middle rook's row is b; at most two columns are ever excluded, so three candidates per side suffice
    for (int b = 1; b + 1 < m; b++)
      for (long[] x : rows[b])
        for (long[] y : pre[b]) {
          if (y[1] == x[1]) continue;
          for (long[] z : suf[b + 1]) {
            if (z[1] == x[1] || z[1] == y[1]) continue;
            best = Math.max(best, x[0] + y[0] + z[0]);
          }
        }
    return best;
  }

  // the best cell of each of the (up to) three best distinct columns among the candidates
  private static long[][] top3(List<long[]> candidates) {
    candidates.sort((a, b) -> Long.compare(b[0], a[0]));
    List<long[]> out = new ArrayList<>();
    for (long[] c : candidates) {
      boolean seen = false;
      for (long[] o : out) if (o[1] == c[1]) seen = true;
      if (!seen) out.add(c);
      if (out.size() == 3) break;
    }
    return out.toArray(new long[0][]);
  }

  private static List<long[]> concat(long[][] a, long[][] b) {
    List<long[]> all = new ArrayList<>(Arrays.asList(a));
    all.addAll(Arrays.asList(b));
    return all;
  }
}
